import React, { useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../App.css";

const MySales = () => {
  const [sales, setSales] = useState([
    {
      id: 1,
      title: "Power Rack",
      price: 399,
      condition: "Good",
      sold: false,
      image: "https://via.placeholder.com/300x200",
    },
    {
      id: 2,
      title: "Elliptical Machine",
      price: 280,
      condition: "Fair",
      sold: true,
      image: "https://via.placeholder.com/300x200",
    },
  ]);

  const toggleSold = (id) => {
    const updated = sales.map((item) =>
      item.id === id ? { ...item, sold: !item.sold } : item
    );
    setSales(updated);
  };

  return (
    <div>
      <Navbar />
      <main className="favorites-wrapper">
        <h2>My Listings for Sale</h2>

        {sales.length === 0 ? (
          <p className="empty-fav">You haven’t posted any listings yet.</p>
        ) : (
          <div className="favorites-grid">
            {sales.map((item) => (
              <div className="favorite-card" key={item.id}>
                <img src={item.image} alt={item.title} />
                <h4>{item.title}</h4>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Price:</strong> ${item.price}</p>
                <button
                  className={item.sold ? "sold-btn" : "mark-sold-btn"}
                  onClick={() => toggleSold(item.id)}
                >
                  {item.sold ? "Mark as Available" : "Mark as Sold"}
                </button>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default MySales;
